class Solution:
    def compress(self, chars: list[str]) -> int:
        read=write=0
        while read<len(chars):
            ch=chars[read];end=read
            while end<len(chars) and chars[end]==ch:end+=1
            chars[write]=ch;write+=1;count=end-read
            if count>1:
                for digit in str(count):chars[write]=digit;write+=1
            read=end
        return write

class Solution {
    public int compress(char[] chars) {
        int read=0,write=0;
        while(read<chars.length){char c=chars[read];int end=read;while(end<chars.length&&chars[end]==c)end++;
            chars[write++]=c;int count=end-read;if(count>1)for(char d:Integer.toString(count).toCharArray())chars[write++]=d;read=end;
        }return write;
    }
}

class Solution:
    def addTwoNumbers(self, l1, l2):
        a=[];b=[]
        while l1:a.append(l1.val);l1=l1.next
        while l2:b.append(l2.val);l2=l2.next
        carry=0;head=None
        while a or b or carry:
            total=carry+(a.pop() if a else 0)+(b.pop() if b else 0)
            node=ListNode(total%10);node.next=head;head=node;carry=total//10
        return head

import java.util.*;
class Solution {
    public ListNode addTwoNumbers(ListNode l1,ListNode l2) {
        Deque<Integer>a=new ArrayDeque<>(),b=new ArrayDeque<>();while(l1!=null){a.push(l1.val);l1=l1.next;}while(l2!=null){b.push(l2.val);l2=l2.next;}
        int carry=0;ListNode head=null;
        while(!a.isEmpty()||!b.isEmpty()||carry>0){int sum=carry+(a.isEmpty()?0:a.pop())+(b.isEmpty()?0:b.pop());ListNode n=new ListNode(sum%10);n.next=head;head=n;carry=sum/10;}
        return head;
    }
}

from collections import defaultdict
class Solution:
    def numberOfArithmeticSlices(self, nums: list[int]) -> int:
        dp=[defaultdict(int) for _ in nums];answer=0
        for i in range(len(nums)):
            for j in range(i):
                diff=nums[i]-nums[j];count=dp[j][diff]
                answer+=count;dp[i][diff]+=count+1
        return answer

import java.util.*;
class Solution {
    public int numberOfArithmeticSlices(int[] nums) {
        int n=nums.length;Map<Long,Integer>[]dp=new Map[n];for(int i=0;i<n;i++)dp[i]=new HashMap<>();int answer=0;
        for(int i=0;i<n;i++)for(int j=0;j<i;j++){long d=(long)nums[i]-nums[j];int count=dp[j].getOrDefault(d,0);answer+=count;dp[i].put(d,dp[i].getOrDefault(d,0)+count+1);}
        return answer;
    }
}

class Solution:
    def findDisappearedNumbers(self, nums: list[int]) -> list[int]:
        for x in nums:nums[abs(x)-1]=-abs(nums[abs(x)-1])
        return [i+1 for i,x in enumerate(nums) if x>0]

import java.util.*;
class Solution {
    public List<Integer> findDisappearedNumbers(int[] nums) {
        for(int x:nums){int i=Math.abs(x)-1;nums[i]=-Math.abs(nums[i]);}
        List<Integer>out=new ArrayList<>();for(int i=0;i<nums.length;i++)if(nums[i]>0)out.add(i+1);return out;
    }
}

class Solution:
    def deleteNode(self, root, key: int):
        if not root:return None
        if key<root.val:root.left=self.deleteNode(root.left,key)
        elif key>root.val:root.right=self.deleteNode(root.right,key)
        else:
            if not root.left:return root.right
            if not root.right:return root.left
            succ=root.right
            while succ.left:succ=succ.left
            root.val=succ.val
            root.right=self.deleteNode(root.right,succ.val)
        return root

class Solution {
    public TreeNode deleteNode(TreeNode root,int key) {
        if(root==null)return null;
        if(key<root.val)root.left=deleteNode(root.left,key);
        else if(key>root.val)root.right=deleteNode(root.right,key);
        else{if(root.left==null)return root.right;if(root.right==null)return root.left;TreeNode s=root.right;while(s.left!=null)s=s.left;root.val=s.val;root.right=deleteNode(root.right,s.val);}
        return root;
    }
}

from collections import Counter
class Solution:
    def frequencySort(self, s: str) -> str:
        return ''.join(c*n for c,n in Counter(s).most_common())

import java.util.*;
class Solution {
    public String frequencySort(String s) {
        Map<Character,Integer>c=new HashMap<>();for(char x:s.toCharArray())c.put(x,c.getOrDefault(x,0)+1);
        List<Character>keys=new ArrayList<>(c.keySet());keys.sort((a,b)->Integer.compare(c.get(b),c.get(a)));
        StringBuilder out=new StringBuilder();for(char x:keys)for(int i=0;i<c.get(x);i++)out.append(x);return out.toString();
    }
}

class Solution:
    def findMinArrowShots(self, points: list[list[int]]) -> int:
        if not points:return 0
        points.sort(key=lambda p:p[1]);arrows=1;end=points[0][1]
        for start,finish in points[1:]:
            if start>end:arrows+=1;end=finish
        return arrows

import java.util.*;
class Solution {
    public int findMinArrowShots(int[][] points) {
        if(points.length==0)return 0;Arrays.sort(points,Comparator.comparingLong(a->(long)a[1]));int arrows=1;long end=points[0][1];
        for(int i=1;i<points.length;i++)if((long)points[i][0]>end){arrows++;end=points[i][1];}
        return arrows;
    }
}

class Solution:
    def minMoves(self, nums: list[int]) -> int:
        m=min(nums)
        return sum(x-m for x in nums)

class Solution {
    public int minMoves(int[] nums) {
        int min=Integer.MAX_VALUE;for(int x:nums)min=Math.min(min,x);long total=0;for(int x:nums)total+=(long)x-min;return (int)total;
    }
}

from collections import Counter
class Solution:
    def fourSumCount(self, nums1, nums2, nums3, nums4) -> int:
        sums=Counter(a+b for a in nums1 for b in nums2)
        return sum(sums[-c-d] for c in nums3 for d in nums4)

import java.util.*;
class Solution {
    public int fourSumCount(int[] a,int[] b,int[] c,int[] d) {
        Map<Integer,Integer>count=new HashMap<>();for(int x:a)for(int y:b)count.put(x+y,count.getOrDefault(x+y,0)+1);
        long ans=0;for(int x:c)for(int y:d)ans+=count.getOrDefault(-x-y,0);return (int)ans;
    }
}
